import re
from collections import Counter

def tokenize(text):
    """Lowercase and extract alphanumeric tokens including apostrophes."""
    return re.findall(r"[a-z0-9']+", text.lower())

def tokens_and_types(text):
    """Return the total count of tokens and unique types."""
    tokens = tokenize(text)
    return (len(tokens), len(set(tokens)))

def top_words(text, k):
    """Return k most frequent tokens, sorted by frequency desc and alphabet asc."""
    counts = Counter(tokenize(text))
    return sorted(counts.items(), key=lambda x: (-x[1], x[0]))[:k]

print(tokens_and_types("Bohat acha match tha, bohat acha!"))

